const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Australia and Indonesia
  const australia = ee.Geometry.Polygon([
    [[113.0, -44.0], [154.0, -44.0], [154.0, -10.0], [113.0, -10.0], [113.0, -44.0]]
  ]);

  const indonesia = ee.Geometry.Polygon([
    [[95.0, -11.0], [141.0, -11.0], [141.0, 6.0], [95.0, 6.0], [95.0, -11.0]]
  ]);

  // 2. Load Sentinel-5P TROPOMI CO data for October 2024
  const startDate = '2024-10-01';
  const endDate = '2024-10-31';

  const colCO = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_CO')
    .filterDate(startDate, endDate)
    .select('CO_column_number_density');

  print('CO Collection size: ' + colCO.size().getInfo());

  // 3. Check if data exists
  const colSize = colCO.size().getInfo();
  if (colSize === 0) {
    print('No Sentinel-5P CO data found for October 2024.');
    print('C1');
    return;
  }

  // 4. Calculate mean CO for Australia
  const coAustralia = colCO.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: australia,
    scale: 5000,
    maxPixels: 1e9
  });

  const meanCO_Australia = coAustralia.get('CO_column_number_density').getInfo();
  const countCO_Australia = colCO.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: australia,
    scale: 5000,
    maxPixels: 1e9
  }).get('CO_column_number_density').getInfo();

  print('Australia: Mean CO = ' + (meanCO_Australia !== null ? meanCO_Australia.toFixed(6) : 'null') + 
        ', Pixels: ' + countCO_Australia);

  // 5. Calculate mean CO for Indonesia
  const coIndonesia = colCO.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: indonesia,
    scale: 5000,
    maxPixels: 1e9
  });

  const meanCO_Indonesia = coIndonesia.get('CO_column_number_density').getInfo();
  const countCO_Indonesia = colCO.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: indonesia,
    scale: 5000,
    maxPixels: 1e9
  }).get('CO_column_number_density').getInfo();

  print('Indonesia: Mean CO = ' + (meanCO_Indonesia !== null ? meanCO_Indonesia.toFixed(6) : 'null') + 
        ', Pixels: ' + countCO_Indonesia);

  // 6. Validation
  if (countCO_Australia === 0 || countCO_Indonesia === 0) {
    print('No valid pixels for one or both regions.');
    print('C2');
    return;
  }

  if (meanCO_Australia === null || meanCO_Indonesia === null) {
    print('CO calculation failed (null values).');
    print('C3');
    return;
  }

  if (meanCO_Australia < 0 || meanCO_Australia > 1000 || 
      meanCO_Indonesia < 0 || meanCO_Indonesia > 1000) {
    print('CO values out of valid range.');
    print('C3');
    return;
  }

  // 7. Compare and answer
  print('Comparison: Australia (' + meanCO_Australia.toFixed(6) + ') vs Indonesia (' + 
        meanCO_Indonesia.toFixed(6) + ')');

  if (meanCO_Australia > meanCO_Indonesia) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
